const KXWV="attribute float aD; varying vec2 vP; varying float vD; void main(){ vP = uv; vD = aD; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }",
KXFV="varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }",
KXFF=`
  uniform float uTime; varying vec2 vUv;
  vec3 sRGB(vec3 c) { return pow(c, vec3(2.2)); }
  void main() {
    float x = vUv.x, s = vUv.y;
    float edge = smoothstep(0.0, 0.24, x) * smoothstep(1.0, 0.76, x);
    float st = 0.5 + 0.5 * sin(x * 26.0 + sin(s * 0.7 - uTime * 3.0) * 1.2 + s * 0.15);
    float fl = fract(s * 0.18 - uTime * 1.4 + x * 0.7);
    float band = smoothstep(0.0, 0.5, fl) * smoothstep(1.0, 0.5, fl);
    float foam = smoothstep(5.0, 0.0, s);
    vec3 col = mix(sRGB(vec3(0.45, 0.78, 1.0)), sRGB(vec3(0.95, 0.99, 1.0)), clamp(st * 0.45 + band * 0.3 + foam * 0.6 + smoothstep(14.0, 44.0, s) * 0.4, 0.0, 1.0));
    float a = edge * (0.55 + 0.35 * st) * smoothstep(46.0, 24.0, s) * smoothstep(0.0, 0.35, s);
    gl_FragColor = vec4(col, a);
    #include <colorspace_fragment>
  }
`,
KXPF=`
  uniform float uTime; varying vec2 vP; varying float vD;
  vec3 sRGB(vec3 c) { return pow(c, vec3(2.2)); }
  float hgt(vec2 p) {
    return 0.5 * sin(p.x * 2.7 + uTime * 1.2 + sin(p.y * 2.1 + uTime * 0.6))
         + 0.5 * sin(p.y * 3.3 - uTime * 1.0 + sin(p.x * 1.9 - uTime * 0.4))
         + 0.2 * sin((p.x + p.y) * 5.1 + uTime * 1.7);
  }
  void main() {
    vec2 p = vP;
    float chan = smoothstep(0.5, 2.8, p.x);
    p.x -= uTime * 0.9 * chan;
    float e = 0.03, h0 = hgt(p);
    vec3 n = normalize(vec3(-(hgt(p + vec2(e, 0.0)) - h0) / e * 0.08, 1.0, -(hgt(p + vec2(0.0, e)) - h0) / e * 0.08));
    float glint = smoothstep(0.996, 1.0, dot(n, normalize(vec3(0.12, 1.0, 0.08))));
    float depth = clamp(vD / 0.34, 0.0, 1.0);
    vec3 col = mix(sRGB(vec3(0.58, 0.92, 0.88)), sRGB(vec3(0.14, 0.48, 0.80)), smoothstep(0.0, 1.0, depth));
    col += sRGB(vec3(0.55, 0.78, 1.0)) * (0.10 + 0.08 * h0);
    float streak = 0.5 + 0.5 * sin(vP.y * 10.0 + sin(p.x * 1.5) * 1.5);
    col = mix(col, vec3(1.0), chan * streak * 0.18 * smoothstep(0.0, 0.08, vD));
    col = mix(col, vec3(1.0), glint * 0.55);
    float foam = smoothstep(0.05, 0.0, vD) * (0.75 + 0.25 * sin(p.x * 5.0 + p.y * 4.0 + uTime * 1.5));
    col = mix(col, vec3(1.0), clamp(foam, 0.0, 1.0) * 0.85);
    float a = smoothstep(0.0, 0.03, vD) * mix(0.84, 0.97, depth);
    gl_FragColor = vec4(col, a);
    #include <colorspace_fragment>
  }
`;
